            '<text x="10" y="22" font-size="14" font-weight="600">NMOS pass (PTL, illustrative)</text>'
            '<line x1="50" y1="105" x2="95" y2="105" stroke="#334" stroke-width="2"/>'
            '<text x="22" y="109" font-size="12">in</text>'
            '<line x1="95" y1="85" x2="140" y2="105" stroke="#630" stroke-width="2"/>'
            '<rect x="140" y="90" width="56" height="30" fill="#ffe8c8" stroke="#630" rx="4"/>'
            '<text x="168" y="108" text-anchor="middle" font-size="11">nmos</text>'
