def waveform_svg(columns: list[str], data_rows: list[list[float]], *, vdd: float) -> str:
    """Simple multi-trace plot (time vs voltage) from ngspice wrdata rows (time + node columns)."""
    if not data_rows or len(columns) < 2:
        return (
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 80">'
            '<text x="8" y="40" font-size="13">No waveform samples</text></svg>'
        )
    n = len(data_rows)
    tcol = [r[0] for r in data_rows]
    traces = [[r[j] for r in data_rows] for j in range(1, len(columns))]
    t0, t1 = tcol[0], tcol[-1]
    if t1 <= t0:
        t1 = t0 + 1e-15
    margin_l, margin_r, margin_t, margin_b = 56, 18, 18, 42
    chart_w, chart_h = 640, 220
    vw = chart_w + margin_l + margin_r
    vh = chart_h + margin_t + margin_b
    colors = ("#0a6", "#06c", "#c60", "#909", "#666", "#a40")
    def sx(ti: float) -> float:
        return margin_l + (ti - t0) / (t1 - t0) * chart_w

    def sy(v: float) -> float:
        return margin_t + chart_h * (1 - min(max(v / vdd, 0), 1))

    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {vw} {vh}" font-family="system-ui,sans-serif">',
        f'<rect x="0" y="0" width="{vw}" height="{vh}" fill="#fafbfd"/>',
        f'<text x="{margin_l}" y="15" font-size="12" fill="#333">Transient waveforms (ngspice wrdata)</text>',
        f'<line x1="{margin_l}" y1="{margin_t + chart_h}" x2="{margin_l + chart_w}" y2="{margin_t + chart_h}" stroke="#888"/>',
        f'<line x1="{margin_l}" y1="{margin_t}" x2="{margin_l}" y2="{margin_t + chart_h}" stroke="#888"/>',
    ]
    # 0 / Vdd ticks
    for lab, frac in (("0", 1.0), ("Vdd", 0.0)):
        yy = margin_t + chart_h * frac
        parts.append(
            f'<line x1="{margin_l - 4}" y1="{yy}" x2="{margin_l + chart_w}" y2="{yy}" stroke="#ddd"/>'
        )
        parts.append(f'<text x="{margin_l - 6}" y="{yy + 4}" text-anchor="end" font-size="10" fill="#666">{lab}</text>')
    for j, (name, ys) in enumerate(zip(columns[1:], traces)):
        if len(ys) != n:
            continue
        color = colors[j % len(colors)]
        d_parts: list[str] = [f"M {sx(tcol[0]):.2f} {sy(ys[0]):.2f}"]
        for i in range(1, n):
            d_parts.append(f"L {sx(tcol[i]):.2f} {sy(ys[i]):.2f}")
        parts.append(
            f'<path d="{" ".join(d_parts)}" fill="none" stroke="{color}" stroke-width="1.6"/>'
        )
        parts.append(
            f'<text x="{margin_l + chart_w - 4}" y="{margin_t + 16 + j * 14}" text-anchor="end" '
            f'font-size="11" fill="{color}">{_xml_text(name)}</text>'
        )
    tx = margin_l + chart_w // 2
    parts.append(
        f'<text x="{tx}" y="{vh - 12}" text-anchor="middle" font-size="10" fill="#555">time (s)</text>'
    )
    parts.append("</svg>")
    return "".join(parts)


def build_visualization_bundle(
    gate_key: str,
    realization: Realization,
    step1: dict[str, Any],
    waveform: dict[str, Any] | None,
    vdd: float,
) -> dict[str, Any]:
    """SVG + Xschem strings for API JSON."""
    ins = list(step1.get("truth_table_input_literals") or [])
    outs = list(step1.get("truth_table_output_literals") or [])
    if not ins or not outs:
        w = len(ins) or len(outs) or 1
        ins = ["A", "B", "C", "D"][:w] if not ins else ins
        outs = ["P", "Q", "R", "S"][:w] if not outs else outs
    eqs = step1.get("equations")
    equations = [str(e) for e in eqs] if isinstance(eqs, list) else None
    subtitle = ", ".join(equations) if equations else str(step1.get("gate", gate_key))
    sch_logic = build_logic_xschem_sch(gate_key, ins, outs, subtitle)
    sch_tx = build_transistor_xschem_sch(gate_key, realization, len(ins))
    svg_logic = logic_diagram_svg(gate_key, ins, outs, equations)
    svg_tx = transistor_diagram_svg(realization, len(ins))

    svg_wf = ""
    if waveform and waveform.get("columns") and waveform.get("rows"):
        cols = [str(c) for c in waveform["columns"]]
        data_rows = waveform["rows"]
        if cols and isinstance(data_rows, list) and len(data_rows) > 0:
            svg_wf = waveform_svg(cols, data_rows, vdd=vdd)

    return {
        "logic_diagram_svg": svg_logic,
        "transistor_diagram_svg": svg_tx,
        "waveform_svg": svg_wf,
        "xschem": {
            "logic_symbol_sch": sch_logic,
            "transistor_schematic_sch": sch_tx,
            "note": (
                "Open `.sch` files in Xschem with default device libraries on the PATH "
                "(symbols such as ipin.sym / nmos4.sym). Files are ASCII — save from the UI download links."
            ),
        },
    }


__all__ = ["build_visualization_bundle", "build_logic_xschem_sch", "build_transistor_xschem_sch"]
